-- Mollem (Bhagwan Mahavir Wildlife Sanctuary) destination_months prose — 12 month-rows
-- Generated 2026-05-10 — S13 Goa batch
-- Voice: locked NakshIQ FT Weekend register
-- destination_id: mollem

INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 1, 5, 'go',
  'Peak Western Ghats post-monsoon. 14-26C, dry. Tambdi Surla 12th C temple and sanctuary trails at full operational tempo.',
  'January is when Bhagwan Mahavir Wildlife Sanctuary runs at its post-monsoon peak. The 240 sq km is Goa''s largest protected area; Mollem range office issues 7am-5pm sanctuary permits at ₹50 per person. Tambdi Surla — the 12th C Kadamba dynasty temple, Goa''s oldest and only surviving pre-Portuguese temple — sits in dense forest 12km from Mollem.',
  NULL,
  'Mollem in January is the version every Western Ghats wildlife regular wants to see. Daytime in the sanctuary sits at 18-26C, mornings drop to 14C, nights at the Mollem range gate touch 12C. The 240 sq km Bhagwan Mahavir Wildlife Sanctuary is Goa''s largest protected area — leopard, sloth bear, gaur, sambar, king cobra and 200+ bird species recorded by Bombay Natural History Society surveys. Mollem range office (Sanguem taluka, on NH4A 60km from Margao) issues sanctuary permits 7am-5pm at ₹50/person plus ₹100/vehicle. Tambdi Surla — the 12th C Kadamba dynasty temple, Goa''s oldest surviving Hindu temple, built in basalt Hemadpanthi style and the only pre-Portuguese temple to survive the 1540 destructions — sits 12km from Mollem range office down a forest road; the temple stands open 6am-6pm with a single Brahmin priest in resident attendance. Stays: Wildernest Resort at Chorla Ghat (₹8-15k, 35km drive but the year-best treehouse base), Mollem Nature Camp (₹3.5-6.5k, basic Forest-Department-aligned), Sahakari Spice Farm Homestay (₹2.5-4.5k, working-farm), Dudhsagar Treehouse (₹5-9k). Netravali Bubbling Lake (30km southeast in Sanguem) is the under-rated half-day spur — natural CO2 bubbles continuously surface in a sacred-grove pool.'
)
