INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 2, 5, 'go',
  'Driest month. 16-28C. Sanctuary tracks firm. Wildlife concentrating at remaining waterholes.',
  'February is the cleanest of the cool Western Ghats months. Rainfall under 10mm, sanctuary tracks at year-firmest, wildlife concentration starts at remaining waterholes from week three. Tambdi Surla 12th C temple at year-best photogenic.',
  NULL,
  'February in Mollem is the technical sweet-spot. Rainfall averages under 10mm, daytime 18-28C, sanctuary tracks at year-firmest. Wildlife sighting probability climbs as Western Ghats waterholes shrink and animals concentrate at remaining streams (Surla, Tambdi, Khandepar) — leopard, sloth bear, and gaur sighting odds peak in late February through April. Tambdi Surla 12th C Kadamba temple — the only pre-Portuguese Hindu temple to survive Goa''s 1540 wave of destructions, built in basalt Hemadpanthi joinery — is at year-best photogenic between 8-9am when forest light catches the eastern-facing sanctum. Wildernest Resort at Chorla Ghat (₹8-15k, 35km drive) holds February as its second-peak booking month after January; book 14-21 days ahead. Mollem Nature Camp walk-in available weekdays. The Mollem-Tambdi Surla 12km forest drive is at year-best — bus to Mollem from Margao via NH4A is 60km, taxi ₹2,500 round-trip from Margao. Sanctuary permit hours 7am-5pm; entry beyond 5pm requires advance Forest Department clearance.'
)
