INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 4, 2, 'wait',
  'Pre-summer heat in valley. 22-33C, humidity 70 percent. Wildlife at waterholes but trails hot.',
  'April still works for the wildlife-only agenda — waterhole concentration peaks, sanctuary still permits 7am-5pm. Trails at 30-33C past 11am. Tambdi Surla forest setting at coolest 6-9am only.',
  'April pushes the Western Ghats sanctuary into pre-summer heat. Sanctuary trails workable only 6-10am and post-4pm; mid-day inside the sanctuary hits 30-33C. Pre-monsoon thunderstorms from late April knock power. Waterhole-watching from a fixed hide is the one workable mid-day option.',
  'April in Mollem is the heat-and-wildlife month. Daytime 23-33C in the sanctuary, humidity climbing past 70 percent, the Western Ghats canopy is leafless after winter and offers thin shade. Wildlife at waterholes is at year-best concentration — gaur in 8-12 individual sightings/morning at Tambdi crossing, sloth bear sighting odds doubled versus January. But sanctuary trails work only 6-10am and post-4pm; mid-day collapses to 30-33C even under canopy. Tambdi Surla 12th C temple at coolest 6-9am — basalt Hemadpanthi structure holds 26-28C interior all day but the 12km forest road in is hot from 10am. Wildernest Resort at Chorla Ghat drops to ₹6,500-7,500 (versus ₹10,000 February); Sahakari Spice Farm Homestay at ₹2,500. Pre-monsoon thunderstorms from April 22-28 bring 30-50mm overnight rains that knock the sanctuary''s patchy electric supply for 2-4 hours. Push to October if heat-tolerance is low.'
)
