INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 5, 2, 'wait',
  'Peak heat. 24-35C, humidity 75 percent. First squalls late month bring leeches. Wildlife waterhole hides only.',
  'Early May still works for the dawn-and-dusk wildlife traveller — waterhole concentration peaks. Last 10 days bring SW-monsoon squalls and leech-prep ground. Skip to October if comfort matters.',
  'May runs hot in the Mollem sanctuary. Trails workable only at the day''s edges (6-9am, post-5pm). Pre-monsoon squalls from May 22 onward bring 30-50mm overnight downpours and start the leech season. Wildernest Resort drops to year-low rates but the trails compress.',
  'May in Mollem is the year''s hottest sanctuary month. Daytime 25-35C, humidity 75 percent, sanctuary trails workable only 6-9am and post-5pm. Pre-monsoon squalls arrive May 22-28 with 30-50mm overnight downpours; these are the leech-season opening rains, ground stays damp from late May onward. Sanctuary permits continue 7am-5pm but the heat-restricted window is genuinely tight. Wildlife waterhole concentration remains visible (gaur, sambar, occasional leopard at the Surla and Tambdi crossings) — fixed-hide positions are the one viable mid-day approach. Tambdi Surla 12th C temple is at coolest 6-9am only; the forest 12km road in is hot from 10am with no AC vehicles available. Wildernest Resort at Chorla Ghat at ₹5,500-6,500, Mollem Nature Camp at ₹3,000. Power supply gets unreliable in pre-monsoon — 2-4 hour cuts daily. Push to October.'
)
