INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 6, 1, 'skip',
  'SW monsoon onset. 22-29C, 800-1000mm rain. Sanctuary closes for safety. Trails leech-heavy. Skip.',
  NULL,
  'June is when the southwest monsoon hits the Western Ghats with full force. Sanctuary trails close for safety under Forest Department rule (landslides, swollen streams, leeches everywhere). Tambdi Surla temple stays open but forest road floods. Skip.',
  'June in Mollem is when the southwest monsoon arrives with peak Western Ghats force. Rainfall hits 800-1000mm across 20-25 wet days. Goa Forest Department closes most sanctuary trails for safety from June 1: landslides on the Mollem-Tambdi Surla forest road, rising stream crossings (Surla and Khandepar both flood after 100mm-plus events), and leech swarms make trail walks dangerous and unpleasant. Bhagwan Mahavir sanctuary entrance permits suspend trail-only access; vehicle drives along NH4A continue but sanctuary-deep tracks are gated. Tambdi Surla 12th C temple stays open with daily morning puja but the 12km forest road floods on heavy days. Wildlife at year-best abundance but unreachable. Wildernest Resort at Chorla Ghat continues operations as a monsoon-stay specialist (rates ₹5,500-7,000, the canopy treehouses are at their best in monsoon green). Mollem Nature Camp closes June-September. Skip unless monsoon-stay at Wildernest is the trip itself.'
)
