INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 7, 1, 'skip',
  'Peak monsoon. 22-28C, 1200-1400mm rain. Sanctuary closed, forest road floods, leeches everywhere. Skip.',
  NULL,
  'July is the year''s wettest month at the Western Ghats — 1200-1400mm rainfall, sanctuary closed for safety, Tambdi Surla forest road sometimes inaccessible. Wait for October.',
  'July in Mollem is the year''s wettest stretch in the Western Ghats. Catchment rainfall hits 1200-1400mm across 25-27 wet days. Goa Forest Department keeps sanctuary trails closed for safety; landslides on the Mollem-Tambdi Surla and Mollem-Sanguem forest roads run 1-2 events per week, washing out access for 24-72 hours. Bhagwan Mahavir Wildlife Sanctuary trail permits suspend. Daytime 22-28C feels mild but the constant rain and 95 percent humidity make outdoor sustained activity impossible. Tambdi Surla 12th C temple is technically open with daily morning puja but the 12km forest road floods on heaviest days; pilgrim traffic to the temple drops to year-low. Wildernest Resort at Chorla Ghat continues as a specialist monsoon-stay base (canopy treehouses, rates ₹5,000-6,500, the Western Ghats green is at year-cinematic) — book 7-10 days ahead. Mollem Nature Camp and most sanctuary-side homestays closed. Skip unless Wildernest monsoon-stay is the trip.'
)
