INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 10, 4, 'go',
  'Sanctuary fully reopens. 20-29C, 200-300mm rain. Forest at year-greenest. Wildlife dispersed but visible.',
  'October is the proper season opener. Sanctuary trails reopen fully from October 1 (matching the Dudhsagar jeep cycle). Forest at year-greenest, trails dry by mid-month, wildlife visible if dispersed across abundant waterholes. Hotel rates 30 percent below December.',
  NULL,
  'October in Mollem is when the Western Ghats sanctuary returns to full operations. Goa Forest Department reopens all sanctuary trail permits from October 1 (matching the Dudhsagar Falls jeep cycle reopening). Daytime 22-29C, rainfall 200-300mm — most in the first 10 days — humidity easing toward 75 percent. The forest is at year-greenest after the southwest monsoon; canopy density at peak, streams running full, the Mollem-Tambdi Surla forest road dries out by October 12-15. Wildlife is dispersed across abundant waterholes — sighting probability lower than the January-March waterhole-concentration peak, but the Western Ghats forest aesthetic is at year-best. Tambdi Surla 12th C temple is at peak photogenic in soft post-monsoon morning light. Stays: Wildernest Resort at Chorla Ghat at ₹6,500-8,500 (versus ₹10,000-12,000 December peak), Mollem Nature Camp at ₹4,000-5,000, Sahakari Spice Farm Homestay at ₹2,500-3,500, Dudhsagar Treehouse at ₹6,000-7,500. Leeches still common on damper trails — full-coverage socks essential through October.'
)
