INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 11, 5, 'go',
  'Peak builds. 16-27C, dry, sanctuary trails firm. Bird-call activity at year-best.',
  'November is when the sanctuary returns to its high-season pattern. Rainfall under 50mm, trails firm, leeches gone by mid-month. Bird call activity peaks (post-monsoon territorial). Hotel rates climb 25 percent across the month.',
  NULL,
  'November in Mollem is the year''s second-cleanest sanctuary month. Daytime 18-27C, nights drop to 16-17C, rainfall under 50mm and almost all in the first week. Sanctuary trails are firm, leeches mostly gone by mid-month. Bird-call activity peaks: post-monsoon territorial calls of Malabar trogon, Sri Lanka frogmouth, white-bellied woodpecker, and the year-best detection probability for Heart-spotted woodpecker. Wildlife waterhole concentration begins building in the last 10 days as the smaller forest streams dry up. Tambdi Surla 12th C temple is at year-best forest-light photogenic 8-9am. Wildernest Resort at Chorla Ghat climbs from ₹7,500 to ₹10,000 across the month; Mollem Nature Camp from ₹4,500 to ₹6,000. Sahakari Spice Farm Homestay walk-in available; Dudhsagar Treehouse ₹6,500-8,500. Sanctuary permit hours hold 7am-5pm. The first three weeks of November are the smart traveller''s window — pre-Christmas rates, full trail tempo.'
)
