INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('mollem', 12, 5, 'go',
  'Peak season. 14-26C, dry, sanctuary at full tempo. Hotel rates 30-40 percent above November.',
  'December is the year''s most reliable Mollem window. Sanctuary trails firm, wildlife waterhole concentration starting to build, Tambdi Surla 12th C temple in clear winter light. Christmas-NY week (Dec 22-Jan 2) drives Wildernest Resort rates 30-40 percent above November.',
  NULL,
  'December in Mollem is operational peak. Daytime 18-26C, nights drop to 14C in the Mollem range and 12C up at Chorla Ghat (820m elevation), rainfall under 30mm. Sanctuary trails at year-firmest; wildlife waterhole concentration is starting to build as smaller forest streams continue to dry through the cool months. Tambdi Surla 12th C temple is at year-best clear-light photogenic in winter air. Christmas-NY week (December 22 to January 2) drives Wildernest Resort at Chorla Ghat from ₹10,000 to ₹14,000-16,000 (the canopy treehouses book out 21-30 days ahead); Mollem Nature Camp from ₹5,500 to ₹7,500-8,500; Sahakari Spice Farm Homestay walk-in tightens but available Tuesday-Wednesday at ₹3,500-4,500. Dudhsagar Falls jeep operations from Collem run at full tempo (the Mollem range office issues both falls and sanctuary permits) — the combined sanctuary-and-falls trip is at year-best feasibility. Pack a fleece for evenings and a torch for sanctuary lodge power-cuts.'
)
